alter table public.users enable row level security;
create policy "Profiles are visible to signed-in users" on public.users for select to authenticated using (true);
create policy "Users insert their own profile" on public.users for insert to authenticated with check (id = public.me());
create policy "Users update their own profile" on public.users for update to authenticated using (id = public.me()) with check (id = public.me());
alter table public.friendships enable row level security;
create policy "See your own friendships" on public.friendships for select to authenticated using (user_id = public.me() or friend_id = public.me());
create policy "Manage your own friendships" on public.friendships for all to authenticated using (user_id = public.me()) with check (user_id = public.me());
alter table public.trips enable row level security;
create policy "See trips you are on or your friends own" on public.trips for select to authenticated using (public.can_see_trip(id));
create policy "Create your own trips" on public.trips for insert to authenticated with check (owner_id = public.me());
create policy "Owners update trips" on public.trips for update to authenticated using (owner_id = public.me()) with check (owner_id = public.me());
create policy "Owners delete trips" on public.trips for delete to authenticated using (owner_id = public.me());
alter table public.trip_members enable row level security;
create policy "See members of visible trips" on public.trip_members for select to authenticated using (public.can_see_trip(trip_id));
create policy "Owners add members, people add themselves" on public.trip_members for insert to authenticated with check (user_id = public.me() or public.owns_trip(trip_id));
create policy "Owners remove members, people leave" on public.trip_members for delete to authenticated using (user_id = public.me() or public.owns_trip(trip_id));
